def find_n(factorial):
    low, high = 1, 10**6
    while low <= high:
        mid = (low + high) // 2
        if math.factorial(mid) == factorial:
            return mid
        elif math.factorial(mid) < factorial:
            low = mid + 1
        else:
            high = mid - 1
    return None

